#!/usr/bin/env bash
# =============================================================================
# frontmatter.sh — Validate frontmatter in Copilot asset files
# =============================================================================
# Checks that prompts, agents, and chatmodes have required frontmatter fields.
#
# Required fields by type:
#   *.prompt.md   → model, description (in YAML frontmatter)
#   *.agent.md    → model, description
#   *.chatmode.md → model, description
#   SKILL.md      → description (in skill header)
#
# USAGE: bash .github/eval/checks/frontmatter.sh
# EXIT:  0 = all valid, 1 = validation errors found
# =============================================================================
set -euo pipefail

ERRORS=0

check_frontmatter() {
  local file="$1"
  local required_field="$2"
  local label="$3"

  if [[ ! -f "$file" ]]; then
    return
  fi

  # Extract YAML frontmatter — handles both multi-line (--- on own line)
  # and single-line (---key: value...---) formats
  local frontmatter
  # Read the first frontmatter block in ONE process. The previous
  # `sed ... | head -20` closed the pipe early; GNU sed treats the
  # resulting SIGPIPE as an error, which `set -o pipefail` turns into an
  # aborted run. BSD sed ignores it, so this only ever failed on CI.
  frontmatter=$(awk '/^---$/{d++; if (d>=2) exit; next} d==1 {print; if (++n>=20) exit}' "$file")

  # Fallback: single-line format where entire file is on one line
  # with ---content--- delimiters (generated by copilot-setup.sh)
  if [[ -z "$frontmatter" ]]; then
    frontmatter=$(awk '{
      if (match($0, /^---[^-].*---/)) {
        s = substr($0, 4)            # strip leading ---
        idx = index(s, "---")        # find closing ---
        if (idx > 0) print substr(s, 1, idx - 1)
      }
    }' "$file")
  fi

  if [[ -z "$frontmatter" ]]; then
    echo "FAIL: $file — no YAML frontmatter found"
    ERRORS=$((ERRORS + 1))
    return
  fi

  # Check for required field in both multi-line and single-line formats
  if ! echo "$frontmatter" | grep -qiE "(^|\s)${required_field}\s*:"; then
    echo "FAIL: $file — missing required field '$required_field'"
    ERRORS=$((ERRORS + 1))
  fi
}

echo "── Checking prompt frontmatter ──"
for f in .github/prompts/*.prompt.md; do
  [[ -e "$f" ]] || continue
  check_frontmatter "$f" "model" "prompt"
  check_frontmatter "$f" "description" "prompt"
done

echo "── Checking agent frontmatter ──"
for f in .github/agents/*.agent.md; do
  [[ -e "$f" ]] || continue
  check_frontmatter "$f" "description" "agent"
done

echo "── Checking chatmode frontmatter (legacy) ──"
# Chat modes are deprecated in favor of Custom Agents (.agent.md). The loop
# stays for back-compat with downstream repos that haven't migrated yet.
if [[ -d .github/chatmodes ]]; then
  for f in .github/chatmodes/*.chatmode.md; do
    [[ -e "$f" ]] || continue
    check_frontmatter "$f" "model" "chatmode"
    check_frontmatter "$f" "description" "chatmode"
  done
fi

echo "── Checking skill descriptions ──"
for f in .github/skills/*/SKILL.md; do
  [[ -e "$f" ]] || continue
  # Skills use a description field in the YAML header or as a markdown line
  if ! head -10 "$f" | grep -qiE "(description|triggers?\s+on)"; then
    # Check if the file has a description-like line in the first 10 lines
    if ! head -10 "$f" | grep -qiE "^#.*\b(use when|triggers|description)\b"; then
      echo "WARN: $f — no clear description found in first 10 lines"
    fi
  fi
done

if [[ $ERRORS -gt 0 ]]; then
  echo ""
  echo "FAIL: $ERRORS frontmatter issue(s) detected"
  exit 1
else
  echo ""
  echo "PASS: All frontmatter checks passed"
  exit 0
fi
